import json
from pathlib import Path


entries = {}


def add(number, xml, reason, notes):
    assert number not in entries
    entries[number] = (xml.strip(), reason, notes)


add('269 A', '''
<p>Pour l'application du régime contingentaire prévu à l'article 362 du code général des impôts, les ministres chargés des outre-mer, de l'agriculture et du budget répartissent, par arrêté conjoint, la quantité annuelle exportable en exonération de soulte en contingents entre les départements et les distilleries. Cette répartition repose sur la moyenne arithmétique des volumes exportés au cours des trois dernières campagnes.</p>
<p>Un arrêté conjoint de ces mêmes ministres fixe les modalités de gestion des contingents et les règles d'organisation de la campagne rhumière. Ces règles portent notamment sur les dates des campagnes, la division de la quantité annuelle en tranches selon la catégorie, les modalités de blocage et de déblocage des tranches et les dérogations à ces mesures. L'arrêté détermine également les modalités de redistribution des contingents entre les départements et les distilleries.</p>
''', "Réécriture à droit constant : les ministres chargés de la répartition sont placés en sujets de l'obligation, et le calcul de référence est isolé dans une phrase. Les règles de gestion, d'organisation et de redistribution restent regroupées dans le second alinéa. Aucune réforme de fond de ce contingent n'est définie par policy.json.", "Les deux alinéas, la moyenne arithmétique sur les trois dernières campagnes et le renvoi à l'article 362 du CGI sont conservés. Ce renvoi a été vérifié dans le corpus public : l'article 362 prévoit le contingent annuel, ses conditions et le caractère non négociable des quantités ; aucun de ces paramètres n'est modifié ici.")

add('270', '''
<p>Pour l'application de l'article 362 du code général des impôts, les rhums et tafias traditionnels exportés des départements d'outre-mer vers la France métropolitaine au-delà du contingent légal sont soumis à une soulte. Le ministre chargé du budget et le ministre chargé de l'outre-mer en fixent le tarif par arrêté conjoint.</p>
''', "Réécriture à droit constant : la condition de dépassement du contingent et la compétence pour fixer le tarif font l'objet de deux phrases. Aucune réforme de fond ni aucun nouveau tarif n'est introduit.", "Le champ reste limité aux rhums et tafias traditionnels exportés des départements d'outre-mer vers la France métropolitaine en dépassement du contingent. Le renvoi à l'article 362 du CGI a été vérifié dans le corpus ; le montant de la soulte reste renvoyé à l'arrêté conjoint, sans chiffrage ajouté.")

add('272', '''
<p>Il est interdit de distiller, en France continentale et en Corse, les mélasses de canne à sucre originaires et en provenance des départements d'outre-mer. Les transferts de mélasse de canne à sucre destinés à la distillation sont également interdits entre les départements d'outre-mer, entre les collectivités d'outre-mer et entre les départements et les collectivités d'outre-mer. Seul un arrêté interministériel du ministre de l'économie et des finances et du ministre chargé des départements d'outre-mer peut déroger à cette interdiction de transfert.</p>
<p>Les transferts de jus de canne à sucre destinés à la distillation de rhum sont interdits à l'intérieur des départements d'outre-mer, à l'exception de La Réunion.</p>
''', "Réécriture à droit constant : les interdictions de distillation et de transfert sont distinguées par des phrases séparées, et la dérogation ministérielle est expressément rattachée aux seuls transferts de mélasse. Aucune réforme de fond n'est appliquée à ce régime.", "Les deux conditions cumulatives d'origine et de provenance, les trois catégories de transferts de mélasse, le champ intérieur aux départements pour le jus et l'exception de La Réunion sont préservés. La note source relative aux articles 5 et 8 de la loi n° 2003-276 du 28 mars 2003 est une indication historique de modification, sans date d'effet nouvelle à en déduire.")

add('275 bis', '''
<p>Pour les produits relevant de la catégorie fiscale des alcools au sens de l'article L. 313-15 du code des impositions sur les biens et services, la quantité d'alcool pur est calculée en multipliant le volume occupé par ces produits à la température de 20 degrés Celsius par leur titre alcoométrique volumique. Ce calcul est effectué, le cas échéant, à l'aide de tables de correction. Le titre alcoométrique volumique est déterminé au moyen d'un alcoomètre conforme à la réglementation en vigueur, au besoin après distillation ou après toute opération donnant des résultats analogues.</p>
''', "Réécriture à droit constant : la formule de calcul, le recours éventuel aux tables de correction et la méthode de détermination du titre sont exprimés dans trois phrases au sein du même alinéa. Aucune réforme de fond des accises n'est introduite.", "La température de 20 degrés Celsius, la multiplication par le titre alcoométrique volumique, la conformité de l'alcoomètre et l'alternative à la distillation sont conservées. Le renvoi à l'article L. 313-15 du code des impositions sur les biens et services est maintenu ; ce code n'est pas disponible dans le corpus public fourni pour une vérification de son contenu.")

add('275 bis B', '''
<p>Les professionnels qui souhaitent être habilités à attester eux-mêmes la garantie du titre des ouvrages déposent une demande auprès de la direction régionale des douanes et droits indirects dont ils dépendent. Sont notamment concernés les fabricants, les importateurs, les acquéreurs intracommunautaires, les commissaires-priseurs judiciaires, les responsables d'un crédit municipal ou d'une société de ventes volontaires de meubles aux enchères publiques et les commissionnaires en garantie. L'habilitation concerne le titre des ouvrages qu'ils produisent ainsi que celui des ouvrages qu'ils importent, introduisent en provenance d'un autre Etat membre de l'Union européenne, vendent ou qui leur sont confiés, lorsque ces derniers sont dépourvus du poinçon de garantie français ou d'un poinçon de titre apposé dans un autre Etat membre de l'Union européenne, dans un autre Etat partie à l'accord instituant l'Espace économique européen ou en Turquie, par un organisme indépendant ou par l'administration compétente de l'Etat concerné selon des normes identiques ou équivalentes à celles exigées en France pour le contrôle et la certification du titre. Le professionnel joint à sa demande le cahier des charges mentionné à l'article 275 bis C.</p>
<p>Pour instruire la demande, l'administration réutilise les informations et les documents à jour qu'elle détient déjà légalement et qu'elle est autorisée à utiliser à cette fin. Le demandeur est dispensé de les produire de nouveau. Ce réemploi s'effectue dans le respect des secrets protégés par la loi. Le demandeur peut obtenir la rectification des informations inexactes le concernant et communiquer les mises à jour nécessaires. Le présent alinéa s'applique aux demandes déposées à compter de son entrée en vigueur.</p>
''', "Droit constant pour les professionnels concernés, les ouvrages, les poinçons reconnus, le service de dépôt et le cahier des charges : la longue phrase est répartie en phrases explicites dans le premier alinéa. Réforme de fond au second alinéa : application de la mesure « Déclarer une fois, corriger à la source » de policy.json aux pièces de cette demande, avec réemploi légal, dispense de doublon, protection des secrets et rectification.", "Le premier alinéa conserve le périmètre des ouvrages et des Etats ainsi que le renvoi à 275 bis C ; les conditions techniques de cet article restent exigibles. La dispense ne vise que les pièces à jour déjà légalement détenues et utilisables pour cette instruction, sans créer d'accès nouveau à des données protégées. Elle est prospective pour les nouvelles demandes et ne modifie aucune convention en cours. Hors des cinq codes, coordonner les exigences documentaires de l'arrêté définissant le cahier des charges prévu au 1° de 275 bis C et les formulaires de demande. Le texte porteur devra fixer l'entrée en vigueur de la nouvelle règle, sans date inventée ici. Aucun alinéa existant n'est déplacé.")

add('275 bis C', '''
<p>Le professionnel conclut la convention d'habilitation avec le directeur interrégional des douanes et droits indirects du ressort dont il relève ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, avec le directeur régional des douanes et droits indirects. La conclusion de cette convention est soumise aux conditions suivantes :</p>
<p>1° Le professionnel s'engage à respecter un cahier des charges qui décrit l'organisation de l'entreprise, la procédure et les méthodes de contrôle permettant de s'assurer du titre des ouvrages, les méthodes utilisées pour attester la garantie du titre et, en cas de marquage au laser, le protocole de sécurité informatique mis en place. Ce cahier des charges mentionne la qualification des personnes responsables de son application. Un arrêté du ministre chargé du budget et du ministre chargé de l'industrie en définit les spécifications techniques ;</p>
<p>2° Si le professionnel ne souhaite pas contrôler lui-même le titre des ouvrages dont il entend attester la garantie du titre, il recourt à des organismes de contrôle agréés mentionnés à l'article L. 832-4 du code de commerce ou à des organismes de contrôle indépendants établis dans d'autres Etats membres de l'Union européenne, dans d'autres Etats parties à l'accord instituant l'Espace économique européen ou en Turquie, offrant des garanties identiques ou équivalentes à celles exigées en France. Le professionnel déclare ces organismes à la direction régionale des douanes et droits indirects ;</p>
<p>3° Le professionnel atteste la garantie du titre des ouvrages dans un local sécurisé de l'entreprise, adapté à la conservation soit des poinçons de garantie métalliques, soit des équipements dédiés à la gravure au laser.</p>
<p>Le directeur interrégional des douanes et droits indirects ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, le directeur régional des douanes et droits indirects accorde l'autorisation d'attester la garantie du titre par le marquage au laser d'un poinçon mentionnée au 2° de l'article L. 833-3 du code de commerce.</p>
<p>L'administration peut vérifier sur pièces et sur place, dans les conditions prévues à l'article L. 36 du livre des procédures fiscales, la capacité du professionnel à respecter le cahier des charges présenté, ainsi que l'existence et la sécurité du local de la marque.</p>
''', "Réécriture à droit constant : les éléments du cahier des charges sont répartis en phrases, et la condition de recours à un organisme extérieur est placée en tête du 2°. Les compétences d'autorisation, le local sécurisé et le pouvoir de contrôle sont explicités sans réforme de fond.", "Les six alinéas, les 1° à 3°, les quatre territoires relevant du directeur régional et les trois renvois externes sont conservés. La dispense documentaire nouvelle de 275 bis B ne dispense pas du respect du cahier des charges ni des contrôles. Les articles L. 832-4 et L. 833-3 du code de commerce et L. 36 du LPF ne figurent pas dans le corpus fourni. La note fixe au 1er juillet 2025 l'entrée en vigueur de la rédaction source en application de l'article 3 du décret n° 2025-583 du 26 juin 2025 ; cette date n'est pas celle d'une réforme proposée.")

add('275 bis D', '''
<p>Le professionnel habilité informe la direction régionale des douanes et droits indirects dont il dépend de toute modification des conditions auxquelles la conclusion de la convention était subordonnée. Il déclare la modification au plus tard quarante jours avant la date envisagée pour sa mise en œuvre.</p>
<p>A compter de la réception de l'avis du professionnel, le directeur interrégional des douanes et droits indirects ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, le directeur régional des douanes et droits indirects dispose de trente jours pour lui faire connaître son agrément ou son opposition à la modification projetée. Il peut, le cas échéant, proposer un avenant à la convention.</p>
''', "Réécriture à droit constant : le professionnel est explicitement chargé de la déclaration, et le point de départ du délai de réponse figure en tête du second alinéa. Aucune réforme de fond ni aucun effet nouveau du silence administratif n'est ajouté.", "Les deux alinéas et les délais distincts de quarante jours avant la mise en œuvre et de trente jours après réception sont maintenus. L'avis continue d'être adressé à la direction régionale, tandis que la décision relève du directeur interrégional ou du directeur régional dans les quatre territoires cités. La faculté de proposer un avenant est conservée sans autorisation tacite inventée.")

add('275 bis E', '''
<p>Le professionnel habilité signale, par tous moyens et dans les meilleurs délais, à la direction régionale des douanes et droits indirects dont il dépend toute difficulté ou tout incident pouvant affecter le titre des ouvrages produits, importés, introduits en provenance d'un autre Etat membre de l'Union européenne, d'un autre Etat partie à l'accord instituant l'Espace économique européen ou de Turquie, vendus ou confiés. Il lui indique également les mesures prises pour y remédier. Les ouvrages dont le titre est affecté sont présentés à un organisme de contrôle agréé mentionné à l'article L. 832-4 du code de commerce ou au bureau de garantie pour y être essayés et marqués. Tout ouvrage fabriqué selon des méthodes différentes de celles prévues par la convention d'habilitation est également présenté à un organisme de contrôle agréé mentionné à l'article L. 832-4 du code de commerce ou au bureau de garantie pour y être essayé et marqué.</p>
<p>Le professionnel habilité informe l'administration, par écrit et dans les meilleurs délais, de tout événement ayant une incidence sur l'application de la convention.</p>
''', "Réécriture à droit constant : le signalement de l'incident et l'indication des mesures correctrices sont distingués, et le traitement des ouvrages fabriqués selon d'autres méthodes est formulé directement. Aucune réforme de fond ne réduit ces obligations de sécurité et d'information.", "Les deux alinéas et leurs modalités différentes sont préservés : signalement par tous moyens pour les difficultés ou incidents, information écrite pour tout événement affectant la convention. Les essais et le marquage restent requis dans les deux cas d'ouvrages visés. Le renvoi à L. 832-4 du code de commerce est conservé sans vérification externe, ce code étant absent du corpus. La note d'entrée en vigueur au 1er juillet 2025, issue de l'article 3 du décret n° 2025-583 du 26 juin 2025, concerne la rédaction source.")

add('275 bis F', '''
<p>La garantie du titre est attestée selon l'une des modalités suivantes :</p>
<p>1° Par l'apposition d'un poinçon de garantie métallique mentionné au 1° de l'article L. 833-3 du code de commerce. La Monnaie de Paris remet les poinçons au professionnel habilité. Celui-ci veille à leur bon état et à leur bonne conservation. Il renvoie les poinçons usés à la direction régionale des douanes et des droits indirects territorialement compétente dans le ressort de laquelle il exerce son activité.</p>
<p>Le professionnel habilité signale immédiatement toute disparition ou tout incident lié à la conservation d'un poinçon de garantie métallique à la direction régionale des douanes et droits indirects mentionnée au premier alinéa du 1°. Cette direction procède alors à une enquête. L'application de la convention est suspendue pendant toute la durée de l'enquête. Durant cette période, le professionnel habilité fait apposer le poinçon par un bureau de garantie ou par un organisme de contrôle agréé mentionné à l'article L. 832-4 du code de commerce. A l'issue de l'enquête, la convention peut être résiliée si la responsabilité du professionnel habilité est établie ;</p>
<p>2° Ou par le marquage au laser, conformément au 2° de l'article L. 833-3 du code de commerce, au moyen de fichiers informatiques contenant la version dématérialisée des poinçons. Des organismes agréés élaborent ces fichiers, les vendent et les transfèrent dans les locaux du professionnel habilité. Leur agrément est délivré par le directeur interrégional des douanes et droits indirects territorialement compétent ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, par le directeur régional des douanes et droits indirects, sur la base d'un dossier attestant de leur compétence, de leur expérience et de leur honorabilité. Un cahier des charges arrêté par le ministre chargé des douanes et le ministre chargé de l'industrie définit leurs missions et les conditions dans lesquelles elles sont exercées. Ces missions comprennent notamment la vérification de la mise en place et de la conformité du protocole de sécurité informatique imposé aux professionnels qui demandent l'autorisation d'attester la garantie du titre par marquage au laser d'un poinçon.</p>
<p>Le professionnel habilité veille au bon état et à la bonne conservation des fichiers. Il signale tout fichier dont le fonctionnement est devenu défectueux à la direction régionale des douanes territorialement compétente dans le ressort de laquelle il exerce son activité.</p>
<p>Le professionnel habilité signale immédiatement tout incident relatif à la protection des fichiers ou toute constatation de duplication ou de disparition de ces fichiers à la direction régionale des douanes et droits indirects mentionnée au premier alinéa du 2°. Cette direction procède alors à une enquête. L'application de la convention est suspendue pendant toute la durée de l'enquête. Durant cette période, le professionnel habilité fait apposer le poinçon par un bureau de garantie ou par un organisme de contrôle agréé mentionné à l'article L. 832-4 du code de commerce. A l'issue de l'enquête, la convention peut être résiliée si la responsabilité du professionnel habilité est établie.</p>
''', "Réécriture à droit constant : les responsabilités de la Monnaie de Paris, du professionnel, des organismes fournisseurs de fichiers et des autorités douanières sont exprimées par des phrases séparées. Les deux circuits de signalement, d'enquête, de suspension et de résiliation demeurent complets. Aucune réforme de fond de la garantie n'est introduite.", "Les six alinéas, les deux subdivisions et les renvois à leurs premiers alinéas sont maintenus à leur place. Incohérence préexistante conservée pour contrôle : le dernier alinéa vise la « direction régionale » mentionnée au premier alinéa du 2°, alors que celui-ci désigne le directeur interrégional et, dans quatre territoires seulement, le directeur régional. Une correction de l'autorité ou du renvoi appelle une coordination expresse. Les mots soudés « agrééspar » et « àl'article » sont corrigés matériellement. Les renvois L. 832-4 et L. 833-3 du code de commerce sont conservés, sans accès à ce code dans le corpus. La note situe la rédaction source au 1er juillet 2025, en application de l'article 3 du décret n° 2025-583 du 26 juin 2025.")

add('275 bis G', '''
<p>Le professionnel habilité établit la liste des personnes désignées pour attester la garantie du titre des ouvrages et la tient à jour. Il signale tout changement à la direction régionale des douanes et droits indirects dont il dépend. Il désigne un responsable de la gestion et de la manipulation des outils et des équipements permettant d'attester cette garantie ou plusieurs responsables si la dimension de l'entreprise le justifie.</p>
''', "Réécriture à droit constant : la tenue de la liste et son actualisation sont reliées explicitement, et la possibilité de désigner plusieurs responsables est rattachée à la dimension de l'entreprise. Aucune réforme de fond des fonctions de contrôle n'est introduite.", "L'alinéa unique, le signalement de tout changement et la double mission de gestion et de manipulation sont conservés. La désignation de plusieurs responsables reste subordonnée à la dimension de l'entreprise, sans seuil d'effectif ajouté.")

add('275 bis H', '''
<p>Un document descriptif accompagne les ouvrages dispensés du poinçon de garantie en application des 1° à 3° de l'article L. 833-2 du code de commerce. Ce document est établi à l'en-tête du professionnel et mentionne le métal et le titre.</p>
''', "Réécriture à droit constant : l'obligation d'accompagner les ouvrages d'un document et les mentions de ce document sont exprimées dans deux phrases. Aucune réforme de fond ni nouvelle dispense de poinçon n'est créée.", "Le champ demeure celui des 1° à 3° de L. 833-2, distinct du champ des seuls 2° et 3° retenu par 275 ter M. Le document reste descriptif, à l'en-tête du professionnel, avec indication du métal et du titre. Le code de commerce est absent du corpus fourni ; le renvoi est conservé sans extrapolation.")

add('275 bis I', '''
<p>Le professionnel habilité tient une comptabilité des ouvrages produits, importés, introduits en provenance d'un autre Etat membre de l'Union européenne, vendus ou confiés. Il adresse à la direction régionale des douanes et droits indirects dont il dépend un état selon la périodicité fixée par la convention, et au moins une fois par an. Cet état indique le nombre d'ouvrages essayés, le nombre d'ouvrages marqués pour chaque type de métal, en or, argent et platine, ainsi que le nombre d'ouvrages reconnus aux titres non légaux. Il distingue les ouvrages marqués par apposition d'un poinçon de garantie métallique de ceux marqués au laser. Le professionnel tient ces informations à jour en permanence et les rend accessibles à l'administration, qui peut en demander la consultation à tout moment.</p>
''', "Réécriture à droit constant : la périodicité de transmission, le contenu de l'état, la distinction des techniques de marquage et l'accès de l'administration sont répartis en phrases. Aucune réforme de fond ni nouvelle donnée à déclarer n'est ajoutée.", "L'alinéa unique et la périodicité au moins annuelle sont conservés. Le décompte par métal concerne les ouvrages marqués ; le nombre d'ouvrages aux titres non légaux n'est pas assorti d'une ventilation nouvelle. Le champ d'introduction mentionne seulement un autre Etat membre de l'Union européenne, comme la source, sans alignement implicite sur le champ plus large de 275 bis E. Le relevé semestriel de 275 ter H appartient à un autre régime.")

add('275 bis J', '''
<p>Le professionnel habilité prélève au hasard des échantillons dans les lots d'ouvrages dont il atteste la garantie du titre. Il effectue ces prélèvements selon le plan d'échantillonnage défini dans la convention.</p>
<p>Il tient les échantillons à la disposition des agents de l'administration pendant le délai fixé dans la convention d'habilitation, afin qu'ils puissent pratiquer les essais et contrôles qu'ils jugent nécessaires. Lors de contrôles inopinés, ces agents peuvent également prélever des échantillons sur les ouvrages en cours de fabrication ou sur ceux que le professionnel détient.</p>
''', "Réécriture à droit constant : le prélèvement aléatoire et son plan sont exprimés séparément, puis le professionnel et les agents sont nommés comme sujets de leurs obligations et pouvoirs. Aucune réforme de fond de l'échantillonnage ou du contrôle n'est introduite.", "Les deux alinéas sont conservés. Le plan et la durée de mise à disposition restent fixés par la convention ; aucun nombre d'échantillons ni délai n'est inventé. Le pouvoir de prélèvement inopiné couvre toujours à la fois les ouvrages en cours de fabrication et les ouvrages détenus.")

add('275 bis K', '''
<p>Le professionnel peut mettre fin à la convention d'habilitation en respectant un préavis d'un mois. Ce préavis court à compter de la réception de son avis par le directeur interrégional des douanes et droits indirects ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, par le directeur régional des douanes et droits indirects.</p>
<p>Le directeur interrégional des douanes et droits indirects ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, le directeur régional des douanes et droits indirects peut résilier d'office la convention d'habilitation si le professionnel ne remplit plus les conditions de sa conclusion ou s'il a manqué aux obligations résultant des articles 275 bis B à 275 bis L. Avant toute décision, le directeur informe le professionnel des motifs susceptibles d'entraîner la résiliation et le met en mesure de présenter ses observations dans un délai de quinze jours. La décision de résiliation est motivée. La résiliation prend effet un mois après la notification de cette décision. Dès l'expiration de ce délai, le professionnel remet à l'administration des douanes et droits indirects les poinçons de titre et les fichiers informatiques contenant la version dématérialisée des poinçons qu'il détient.</p>
''', "Réécriture à droit constant : le préavis et son point de départ sont distingués, et la procédure de résiliation d'office suit l'ordre des motifs, des observations, de la décision et de ses effets. Aucune réforme de fond de la résiliation n'est introduite.", "Les deux alinéas restent en place ; le mois de préavis à réception, les quinze jours d'observations et le mois après notification sont conservés. Le renvoi 275 bis B à 275 bis L demeure intégral. Ecart terminologique préexistant à contrôler : la restitution vise les « poinçons de titre », alors que 275 bis F vise des « poinçons de garantie métalliques ». Le terme source est conservé, sans substitution silencieuse. La simplification documentaire de 275 bis B ne modifie pas les conditions techniques des conventions anciennes.")

add('275 bis L', '''
<p>Les conventions d'habilitation ont une durée d'un an et peuvent être renouvelées par tacite reconduction.</p>
''', "Réécriture à droit constant : l'objet des conventions est précisé et leur durée est exprimée directement. Le renouvellement par tacite reconduction est conservé, sans réforme de fond ni changement de durée.", "La durée d'un an et le mécanisme de tacite reconduction sont maintenus. Aucun nouveau délai de dénonciation n'est ajouté ; la cessation demeure régie notamment par 275 bis K.")

add('275 ter', '''
<p>Pour attester la garantie du titre des ouvrages en métaux précieux, les organismes de contrôle mentionnés à l'article L. 832-4 du code de commerce doivent obtenir un agrément lorsque ces ouvrages sont dépourvus d'un poinçon de garantie français ou d'un poinçon de titre apposé dans un autre Etat membre de l'Union européenne, dans un autre Etat partie à l'accord instituant l'Espace économique européen ou en Turquie. Le poinçon de titre ainsi reconnu est celui qu'un organisme indépendant ou l'administration compétente de l'Etat concerné a apposé selon des normes identiques ou équivalentes à celles exigées en France pour le contrôle et la certification du titre.</p>
''', "Réécriture à droit constant : la nécessité de l'agrément est exposée d'abord, puis les conditions tenant à l'auteur et aux normes du poinçon étranger sont précisées dans une seconde phrase. Aucune réforme de fond de la reconnaissance des poinçons n'est introduite.", "Le champ des ouvrages en métaux précieux, les Etats concernés et les exigences de contrôle et de certification sont maintenus. Le renvoi à L. 832-4 du code de commerce est conservé ; ce code n'est pas fourni. La note d'entrée en vigueur au 1er juillet 2025, issue de l'article 3 du décret n° 2025-583 du 26 juin 2025, se rapporte au texte source et non à la dispense documentaire nouvelle proposée à 275 ter B.")

add('275 ter A', '''
<p>Les organismes de contrôle agréés sont établis sur le territoire national. Ils respectent leurs obligations fiscales et douanières et souscrivent une assurance couvrant leur responsabilité civile professionnelle. Leur personnel comprend des cadres qualifiés de laboratoires chargés des méthodes de détermination du titre. Les organismes respectent également les prescriptions du cahier des charges mentionnées au deuxième alinéa de l'article 275 ter B.</p>
''', "Réécriture à droit constant : les conditions d'établissement, de conformité fiscale et douanière, d'assurance, de qualification et de respect du cahier des charges sont formulées directement. Le sujet de la dernière obligation est explicité. Aucune réforme de fond de l'agrément n'est introduite.", "Le renvoi au deuxième alinéa de 275 ter B est conservé et vérifié : le cahier des charges y reste situé, l'alinéa nouveau de simplification étant ajouté en fin d'article. La qualification des cadres de laboratoires et l'assurance de responsabilité civile professionnelle sont maintenues. L'obligation d'établissement national n'est pas étendue aux organismes étrangers auxquels le professionnel peut recourir dans le régime distinct de 275 bis C.")

add('275 ter B', '''
<p>L'organisme qui demande son agrément en qualité d'organisme de contrôle dépose sa demande auprès du directeur interrégional des douanes et droits indirects territorialement compétent ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, auprès du directeur régional des douanes et droits indirects.</p>
<p>Il joint à la demande un cahier des charges décrivant son organisation, la procédure et les méthodes de contrôle et d'essai permettant de s'assurer du titre des ouvrages, les méthodes utilisées pour attester la garantie du titre et, en cas de marquage au laser, le protocole de sécurité informatique mis en place. Un arrêté du ministre chargé du budget et du ministre chargé de l'industrie définit les spécifications techniques de ce cahier des charges.</p>
<p>L'organisme joint également à la demande son numéro unique d'identification, un organigramme faisant apparaître ses responsabilités et ses structures de décision, ainsi que ses deux derniers comptes annuels si son antériorité le permet.</p>
<p>Le directeur interrégional des douanes et droits indirects ou, en Guadeloupe, en Guyane, à La Réunion et à Mayotte, le directeur régional des douanes et droits indirects accorde l'autorisation d'attester la garantie du titre par le marquage au laser d'un poinçon mentionnée au 2° de l'article L. 833-3 du code de commerce.</p>
<p>Pour instruire la demande, l'administration réutilise les informations et les documents à jour qu'elle détient déjà légalement et qu'elle est autorisée à utiliser à cette fin. Le demandeur est dispensé de les produire de nouveau. Ce réemploi s'effectue dans le respect des secrets protégés par la loi. Le demandeur peut obtenir la rectification des informations inexactes le concernant et communiquer les mises à jour nécessaires. Le présent alinéa s'applique aux demandes déposées à compter de son entrée en vigueur.</p>
''', "Droit constant pour les autorités, le contenu du cahier des charges, les pièces requises et l'autorisation de marquage au laser : l'organisme et l'autorité deviennent les sujets explicites. Réforme de fond limitée au cinquième alinéa : réemploi légal des informations et pièces déjà détenues, dispense de nouvelle production, protection des secrets et rectification, conformément à la mesure de simplification administrative de policy.json.", "Les quatre alinéas sources restent à leur place, notamment le deuxième visé par 275 ter A. Les deux derniers comptes demeurent requis sous la réserve liée à l'antériorité de l'organisme ; une pièce périmée ne fonde pas la dispense. Hors des cinq codes, coordonner les formulaires et l'arrêté des ministres chargés du budget et de l'industrie définissant les spécifications techniques au deuxième alinéa de 275 ter B, sans modifier les contrôles ni les agréments existants. Le nouvel alinéa ne concerne que les demandes déposées à compter de son entrée en vigueur, à fixer par le texte porteur. La note source renvoie à l'article 3 du décret n° 2025-583 du 26 juin 2025 et fixe au 1er juillet 2025 l'entrée en vigueur du texte source ; cette date ne vaut pas date de la nouvelle réforme. Le renvoi à L. 833-3 du code de commerce est conservé ; son texte n'est pas dans le corpus autorisé.")

add('275 ter C', '''
<p>Le directeur interrégional ou le directeur régional des douanes et droits indirects compétent mentionné à l'article 275 ter B délivre l'agrément par décision.</p>
''', "Réécriture à droit constant : l'autorité compétente devient le sujet de la décision d'agrément. Le renvoi territorial reste inchangé ; aucune réforme de fond de la délivrance n'est ajoutée.", "Le renvoi à 275 ter B est vérifié et conservé, sans déplacement de l'alinéa qui désigne les autorités. La note source de l'article 42 du décret n° 2020-68 du 30 janvier 2020 doit rester applicable : entrée en vigueur le 1er février 2020 et maintien des dispositions applicables à la date de présentation pour les demandes de décisions administratives individuelles présentées avant cette date. Cette transition n'est ni supprimée ni réaffectée à la réforme documentaire nouvelle.")

add('275 ter D', '''
<p>Le directeur interrégional ou le directeur régional des douanes et droits indirects compétent mentionné à l'article 275 ter B prononce le retrait de l'agrément par une décision motivée. Le retrait peut intervenir à la demande de l'organisme. Le directeur peut également le prononcer d'office si l'organisme ne remplit plus les conditions de l'agrément ou s'il a manqué aux obligations résultant des articles 275 ter à 275 ter P. Avant un retrait d'office, le directeur informe l'organisme des motifs susceptibles de justifier ce retrait et le met en mesure de présenter ses observations dans un délai de trente jours.</p>
<p>L'organisme qui ne remplit plus les conditions prévues par les articles 275 ter à 275 ter P demande le retrait de son agrément et cesse sans délai d'attester la garantie du titre.</p>
''', "Réécriture à droit constant : la compétence de retrait, les deux modes de saisine et le contradictoire préalable au retrait d'office sont distingués. L'obligation de demander le retrait et de cesser l'activité est formulée directement. Aucune réforme de fond n'est introduite.", "Les deux alinéas, la motivation dans tous les cas, le délai de trente jours en cas de retrait d'office et la cessation sans délai sont conservés, ainsi que la plage 275 ter à 275 ter P. Les articles 275 ter N et P consultés dans le corpus confirment les obligations de signalement et la procédure en cas d'incident ; ils ne sont pas modifiés. La note de l'article 42 du décret n° 2020-68 du 30 janvier 2020 fixe l'entrée en vigueur au 1er février 2020. Les demandes de décisions administratives individuelles présentées avant cette date restent soumises aux dispositions applicables à la date de leur présentation ; cette transition demeure applicable.")

add('275 ter E', '''
<p>Le directeur interrégional ou le directeur régional des douanes et droits indirects compétent mentionné à l'article 275 ter B contrôle les organismes de contrôle agréés. Lorsqu'un organisme ne respecte pas ses obligations, ce directeur peut suspendre son agrément sans délai, à titre conservatoire. La procédure de retrait est alors engagée immédiatement.</p>
''', "Réécriture à droit constant : le contrôle, la suspension conservatoire et l'engagement immédiat du retrait sont exprimés dans trois phrases. Aucune réforme de fond ni nouvelle condition de suspension n'est ajoutée.", "Le renvoi à 275 ter B et l'alinéa unique sont conservés. La suspension reste facultative, conservatoire et sans délai ; l'engagement de la procédure de retrait est immédiat, sans confondre suspension et retrait définitif. La note issue de l'article 42 du décret n° 2020-68 du 30 janvier 2020 fixe l'entrée en vigueur au 1er février 2020. Les demandes de décisions administratives individuelles présentées avant cette date demeurent soumises aux dispositions applicables à la date de leur présentation ; cette réserve historique reste applicable.")

add('275 ter G', '''
<p>La garantie du titre est attestée selon l'une des modalités suivantes :</p>
<p>1° Par l'apposition du poinçon de garantie métallique mentionné au 1° de l'article L. 833-3 du code de commerce. Ce poinçon porte un signe caractéristique spécifique à l'ensemble des organismes de contrôle agréés qui attestent la garantie du titre des ouvrages ;</p>
<p>2° Ou par le marquage au laser, conformément au 2° de l'article L. 833-3 du code de commerce, au moyen de fichiers informatiques contenant la version dématérialisée des poinçons. Des organismes agréés élaborent ces fichiers, les vendent et les transfèrent dans les locaux de l'organisme de contrôle agréé. Leur agrément est délivré par le directeur interrégional ou régional compétent mentionné au 2° de l'article 275 bis F, sur la base d'un dossier attestant de leur compétence, de leur expérience et de leur honorabilité. Un cahier des charges arrêté par le ministre chargé des douanes et le ministre chargé de l'industrie définit les missions de ces organismes et les conditions dans lesquelles elles sont exercées. Ces missions comprennent notamment la vérification de la mise en place et de la conformité du protocole de sécurité informatique imposé aux professionnels qui demandent l'autorisation d'attester la garantie du titre par marquage au laser d'un poinçon.</p>
''', "Réécriture à droit constant : les deux techniques de marquage restent distinctes ; les tâches des fournisseurs de fichiers et les conditions de leur agrément sont décomposées en phrases. Aucune réforme de fond des signes, fichiers ou contrôles de sécurité n'est introduite.", "Les trois alinéas, les 1° et 2°, le signe commun à l'ensemble des organismes et les critères de compétence, d'expérience et d'honorabilité sont conservés. Le renvoi au 2° de 275 bis F a été vérifié ; les renvois à L. 833-3 sont maintenus, le code de commerce étant absent du corpus. Point préexistant à contrôler dans le cahier des charges : le texte vise les protocoles imposés aux « professionnels » alors que les fichiers sont transférés dans les locaux d'un organisme de contrôle agréé ; cette formulation n'est pas étendue silencieusement. La note de l'article 3 du décret n° 2025-583 du 26 juin 2025 fixe l'entrée en vigueur de la source au 1er juillet 2025, sans fixer celle d'une réforme proposée.")

add('275 ter H', '''
<p>L'organisme de contrôle agréé adresse à la direction régionale des douanes et droits indirects dont il dépend un relevé semestriel. Ce relevé indique le nombre d'ouvrages essayés, le nombre d'ouvrages dont la garantie a été refusée pour chaque type de métal, en or, argent et platine, et le nombre d'ouvrages marqués pour chacun de ces métaux. Il distingue les ouvrages marqués par apposition d'un poinçon de garantie métallique de ceux marqués au laser. Il distingue également les ouvrages que l'organisme a contrôlés et marqués pour le compte de professionnels non habilités de ceux qu'il a essayés et, le cas échéant, marqués pour le compte de professionnels habilités par une convention passée avec l'administration dans les conditions prévues à l'article L. 832-4 du code de commerce. L'organisme fournit aussi une liste indiquant le nom et l'adresse de ses clients, en distinguant les professionnels habilités des professionnels non habilités. Il tient ces informations à jour en permanence et les rend accessibles à l'administration, qui peut les consulter à tout moment.</p>
''', "Réécriture à droit constant : le contenu du relevé semestriel, les deux distinctions à y faire et la liste des clients sont exprimés dans des phrases séparées. La tenue permanente et la consultation sont explicites. Aucune réforme de fond ni suppression de données de contrôle n'est introduite.", "L'alinéa unique est préservé. Le relevé reste semestriel, distinct de l'état au moins annuel de 275 bis I. Les ventilations des refus et des marquages par métal, les deux techniques, les deux catégories de professionnels et le nom et l'adresse des clients sont maintenus. Le renvoi à L. 832-4 est conservé, sans possibilité de consulter le code de commerce dans le corpus fourni. La note de l'article 3 du décret n° 2025-583 du 26 juin 2025 fixe l'entrée en vigueur de la source au 1er juillet 2025, sans calendrier nouveau.")

add('275 ter M', '''
<p>Les organismes de contrôle agréés garantissent le titre des ouvrages selon les trois modalités suivantes :</p>
<div><p>1° Après essais, ils apposent eux-mêmes le poinçon de garantie métallique ou appliquent un poinçon par marquage au laser sur les ouvrages dépourvus du poinçon de garantie français ou d'un poinçon de titre apposé dans un autre Etat membre de l'Union européenne, dans un autre Etat partie à l'accord instituant l'Espace économique européen ou en Turquie. Le poinçon de titre ainsi reconnu doit avoir été apposé par un organisme indépendant ou par l'administration compétente de l'Etat concerné, selon des normes identiques ou équivalentes à celles exigées en France pour le contrôle et la certification du titre ;</p></div>
<div><p>2° Pour les ouvrages apportés par des professionnels habilités par une convention passée avec l'administration dans les conditions prévues à l'article L. 832-4 du code de commerce, ils procèdent aux essais et, le cas échéant, apposent le poinçon de garantie métallique ou appliquent un poinçon par marquage au laser. Cette modalité concerne les ouvrages dépourvus du poinçon de garantie français ou d'un poinçon de titre apposé dans un autre Etat membre de l'Union européenne, dans un autre Etat partie à l'accord instituant l'Espace économique européen ou en Turquie, par un organisme indépendant ou par l'administration compétente de l'Etat concerné, selon des normes identiques ou équivalentes à celles exigées en France pour le contrôle et la certification du titre ;</p></div>
<div><p>3° Pour les ouvrages dispensés de poinçon en application des 2° et 3° de l'article L. 833-2 du code de commerce, ils certifient le titre de l'ouvrage en délivrant un document.</p></div>
''', "Réécriture à droit constant : la qualité des apporteurs est placée en tête du 2°, et les conditions de reconnaissance des poinçons étrangers sont réparties en phrases sans raccourcir leur contenu. Les essais, le marquage et la certification documentaire restent distincts. Aucune réforme de fond de la garantie n'est introduite.", "Les quatre alinéas, les trois subdivisions et leurs conteneurs sont conservés. Le 1° ne se voit pas ajouter une restriction aux seuls professionnels non habilités, absente de sa formulation source, malgré le recoupement avec le 2° ; l'éventuelle clarification relève d'une coordination expresse avec 275 ter H. Au 2°, le caractère éventuel du marquage est conservé ; au 3°, seuls les 2° et 3° de L. 833-2 sont visés, à la différence de 275 bis H. Les renvois au code de commerce restent inchangés, son texte n'étant pas dans le corpus fourni. La note source de l'article 3 du décret n° 2025-583 du 26 juin 2025 mentionne une entrée en vigueur le 1er juillet 2025 ; aucune nouvelle date n'en est déduite.")


sources = json.loads(Path('source.json').read_text())
assert len(sources) == len(entries) == 24
assert set(entries) == {a['number'] for a in sources}
answer = []
for source in sources:
    xml, reason, notes = entries[source['number']]
    answer.append({
        **{key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')},
        'proposed_xml': xml,
        'reason': reason,
        'review_notes': notes,
        'status': 'rewrite_draft',
    })
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles')
